 'Eastern Province',
 'Qassim',
 'Asir',
 'Tabuk',
 'Hail',
 'Northern Borders',
 'Jazan',
 'Najran',
 'Al Bahah',
 'Al Jawf',
]
export const STAGES: Stage[] = [
 'Discovered',
 'Digitally Assessed',
 'Validated',
 'Development',
 'High Potential',
 'Elite Pathway',
 'International Competition',
 'International Medal',
]
export const PATHWAYS = [
 'Foundation',
 'Youth Development',
 'Performance Development',
