const AV = ['#35e0ff', '#34e3a4', '#ffc24b', '#9a7bff', '#4d8dff', '#2fe6c4', '#ff8fa3']
export const avatarColor = (i: number) => AV[i % AV.length]
export const initials = (n: string) =>
 n
 .split(' ')
 .map((w) => w[0])
 .slice(0, 2)
 .join('')
 .toUpperCase()

// Saudi Arabic names carrying explicit gender so the generated gender stays consistent.
interface SeedName {
 name: string
 gender: 'M' | 'F'
}
const NAMES: SeedName[] = [
 { name: 'Omar Al-Harbi', gender: 'M' },
 { name: 'Sara Al-Qahtani', gender: 'F' },
 { name: 'Faisal Al-Qahtani', gender: 'M' },
 { name: 'Noura Al-Harbi', gender: 'F' },
 { name: 'Abdullah Al-Otaibi', gender: 'M' },
 { name: 'Reem Al-Ghamdi', gender: 'F' },
 { name: 'Mohammed Al-Shehri', gender: 'M' },
 { name: 'Layan Al-Otaibi', gender: 'F' },
 { name: 'Khalid Al-Ghamdi', gender: 'M' },
 { name: 'Hala Al-Dosari', gender: 'F' },
 { name: 'Saud Al-Mutairi', gender: 'M' },
 { name: 'Dana Al-Zahrani', gender: 'F' },
 { name: 'Abdulrahman Al-Dosari', gender: 'M' },
 { name: 'Mariam Al-Shammari', gender: 'F' },
 { name: 'Youssef Al-Zahrani', gender: 'M' },
 { name: 'Abeer Al-Anazi', gender: 'F' },
 { name: 'Nawaf Al-Shammari', gender: 'M' },
 { name: 'Lama Al-Mutairi', gender: 'F' },
 { name: 'Sultan Al-Hazmi', gender: 'M' },
 { name: 'Rawan Al-Hazmi', gender: 'F' },
 { name: 'Ahmed Al-Anazi', gender: 'M' },
 { name: 'Turki Al-Rashidi', gender: 'M' },
 { name: 'Bandar Al-Harbi', gender: 'M' },
 { name: 'Rakan Al-Qahtani', gender: 'M' },
 { name: 'Ziyad Al-Ghamdi', gender: 'M' },
]

function rng(seed: number) {
 let s = seed
 return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
}

// Weighted toward earlier lifecycle stages (realistic pipeline shape).
const STAGE_WEIGHTS = [0.3, 0.24, 0.18, 0.12, 0.08, 0.045, 0.025, 0.01]
function pickStage(x: number): Stage {
 let acc = 0
 for (let i = 0; i < STAGE_WEIGHTS.length; i++) {
 acc += STAGE_WEIGHTS[i]
 if (x <= acc) return STAGES[i]
 }
 return STAGES[STAGES.length - 1]
}

export const ATHLETES: Athlete[] = NAMES.map((p, i) => {
 const r = rng(i * 97 + 7)
 const potential = Math.round(58 + r() * 40)
 const injuryRisk = Math.round(r() * 70)
 const momentum = Math.round((r() - 0.35) * 80)
 const status: Status = injuryRisk > 62 ? 'red' : injuryRisk > 42 ? 'amber' : potential > 88 ? 'cyan' : 'green'
 const stage = pickStage(r())
 return {
 id: 'ATH-' + (1024 + i),
 name: p.name,
 sport: SPORTS[Math.floor(r() * SPORTS.length)],
 region: REGIONS[Math.floor(r() * REGIONS.length)],
 age: Math.round(11 + r() * 21),
 gender: p.gender,
 stage,
 pathway: PATHWAYS[Math.floor(r() * PATHWAYS.length)],
 source: SOURCES[Math.floor(r() * SOURCES.length)],
 potential,
 readiness: Math.round(60 + r() * 38),
 momentum,
 injuryRisk,
 benchmark: Math.round(40 + r() * 59),
 status,
 wearable: Math.round(55 + r() * 44),
 vision: Math.round(62 + r() * 36),
 flag:
 injuryRisk > 62
 ? 'Load spike detected'
 : potential > 90
 ? 'Breakout trajectory'
 : momentum < -20
 ? 'Momentum decline'
 : undefined,
 }
})

// KPI series for command center
export interface Kpi {
 id: string
 label: string
 value: number
 unit?: string
 delta: number
 status: Status
 benchmark?: string
 spark: number[]
 icon: string
}

const spark = (seed: number, n = 16) => {
 const r = rng(seed)
 let v = 40 + r() * 20
 const out: number[] = []
 for (let i = 0; i < n; i++) {
 v = Math.max(8, Math.min(95, v + (r() - 0.45) * 16))
 out.push(v)
 }
 return out
}

