 <div className="ci-insight"><span className="ci-insight__icon">◆</span><div className="ci-insight__txt" style={{ fontSize: 12 }}><b>Recommended:</b> {data.rec}</div></div>
 </>;
 actions = ["Recommend Development Plan", "Create Intervention"];
 } else if (kind === "risk") {
 title = data.subject; sub = `${data.sev} · open ${data.age}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 14 }}>
 {stat(<Chip status={data.sev === "CRITICAL" ? "red" : data.sev === "HIGH" ? "amber" : "cyan"}>{data.sev}</Chip>, "Severity")}
 {stat(data.count, "Affected")}
 {stat(data.owner, "Owner")}
 {stat(data.age, "Time open")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.issue}. Recommended next step: <b style={{ color: "var(--ci-text)" }}>{data.next}</b>.</p>
 </>;
 actions = ["Investigate", "Create Intervention", "Assign Specialist", "Schedule Assessment"];
 } else if (kind === "velo") {
 if (data) {
 title = data.name; sub = `${data.sport} · ${data.region} · age ${data.age} · ${data.stage}`;
 body = <>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(3,1fr)", gap: 12, marginBottom: 14 }}>
 {stat("P" + data.perf, "Benchmark")}
