 {stat(data.conf, "Confidence")}
 </div>
 <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>{data.perf < 50 && data.growth > 50 ? "Emerging athlete accelerating faster than cohort — strong candidate for accelerated assessment." : "Tracking within expected development band."}</p>
