 actions = data.actions.concat(["Investigate"]);
 } else if (kind === "pipeline") {
 title = "Pathway Analysis"; sub = "Conversion & leakage across the national pipeline";
 body = <p className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5 }}>Detailed stage-by-stage conversion analysis. Largest leakage occurs at <b style={{ color: "var(--ci-amber)" }}>Validated → Development</b> (43% progression) — the clearest lever for expanding the development pool.</p>;
 actions = ["Investigate", "Create Intervention"];
 }

 return (
 <Drawer open onClose={onClose} title={title} sub={sub}
 footer={<ActionRow actions={actions} onAction={onAction} />}>
 {body}
 </Drawer>
 );
}
","import React from "react";
import { Drawer } from "../../Drawer";
import { Button } from "../../Button";
import { Chip } from "../../KpiCard";
import { Icon } from "../../Icons";
import { useApp } from "../../../context/AppContext";
import { useCmd, CmdDrawerState } from "./ctx";
import {
 PIPELINE, stageAnalysis, pathwayGapText, STAGE_BARRIERS,
 STAGE_REGION_SPLIT, STAGE_SPORT_SPLIT, STAGE_SOURCE_SPLIT, STAGE_ATTENTION,
 SplitRow, AttentionAthlete,
} from "../../../data/command";

const fmt = (n: number) => n.toLocaleString();
const PRI: Record<string, "red" | "amber" | "cyan"> = { High: "red", Medium: "amber", Low: "cyan" };

type Tab = "overview" | "region" | "sport" | "source" | "athletes";

function Kpi({ v, l, tone }: { v: React.ReactNode; l: string; tone?: string }) {
 return (
 <div className="sd-kpi">
 <div className="sd-kpi__v" style={tone ? { color: tone } : undefined}>{v}</div>
 <div className="sd-kpi__l">{l}</div>
 </div>
 );
}

function SplitBars({ rows, population, selected, onPick, badge }:
 { rows: SplitRow[]; population: number; selected: string | null;
 onPick: (n: string) => void; badge?: (r: { name: string; conv: number; backlog: number }) => React.ReactNode }) {
 const computed = rows.map(r => {
 const pop = Math.round(population * r.share);
 const prog = Math.round(pop * r.conv / 100);
 return { name: r.name, conv: r.conv, pop, prog, backlog: pop - prog };
 });
 const maxPop = Math.max(...computed.map(c => c.pop));
 return (
 <div className="sd-splits">
 {computed.map(c => {
 const sel = selected === c.name;
 return (
 <div key={c.name} className={`sd-split${sel ? " sd-split--sel" : ""}`} onClick={() => onPick(c.name)}>
 <div className="sd-split__top">
 <span className="sd-split__name">{c.name}</span>
 <span className="sd-split__nums">
 <b style={{ color: "var(--ci-text)" }}>{fmt(c.pop)}</b>
 <span className="ci-faint"> · {fmt(c.prog)} progressed · </span>
 <b style={{ color: c.conv >= 48 ? "var(--ci-green)" : c.conv >= 40 ? "var(--ci-cyan)" : "var(--ci-amber)" }}>{c.conv}%</b>
 {badge && badge(c)}
 </span>
 </div>
 <div className="sd-split__track">
 <div className="sd-split__fill" style={{ width: `${(c.pop / maxPop) * 100}%` }} />
 <div className="sd-split__conv" style={{ width: `${(c.pop / maxPop) * (c.conv / 100) * 100}%` }} />
 </div>
 </div>
 );
 })}
 </div>
 );
}

export function StageDrawer({ state, onClose }: { state: CmdDrawerState | null; onClose: () => void }) {
 const { open, setStage, toast } = useCmd();
 const { navigate } = useApp();
 const broad = state?.kind === "pipeline";
 const idx: number = broad ? -1 : (state?.data?.index ?? 0);

 const [tab, setTab] = React.useState<Tab>("overview");
 const [barrier, setBarrier] = React.useState<string | null>(null);
 const [regionF, setRegionF] = React.useState<string | null>(null);
 const [sportF, setSportF] = React.useState<string | null>(null);
 const [preview, setPreview] = React.useState<AttentionAthlete | null>(null);
 const [cohort, setCohort] = React.useState(false);
 const [cohortDone, setCohortDone] = React.useState(false);

 React.useEffect(() => { setTab("overview"); setBarrier(null); setRegionF(null); setSportF(null); setPreview(null); setCohort(false); setCohortDone(false); }, [state?.kind, idx]);

 if (!state) return null;

 // ---------- BROAD: National Pathway Analysis ----------
 if (broad) {
 const transitions = [];
 for (let i = 0; i < PIPELINE.length - 1; i++) transitions.push(stageAnalysis(i));
 const worst = transitions.reduce((a, b) => (b.gap < a.gap ? b : a), transitions[0]);
 return (
 <Drawer open wide onClose={onClose} title="National Pathway Analysis"
 headExtra={<div className="sd-eyebrow">Pipeline Analysis</div>}
 sub="Conversion & progression across the full national pipeline">
 <div className="ci-insight" style={{ marginBottom: 14 }}>
 <span className="ci-insight__icon">◆</span>
 <div className="ci-insight__txt" style={{ fontSize: 12 }}>
 Largest current pathway gap: <b>{worst.from.label} → {worst.to.label}</b> — {worst.rate}% progression ({worst.gap} pts vs {worst.target}% target).
 </div>
 </div>
 <div className="sd-translist">
 {transitions.map(t => {
 const isWorst = t.index === worst.index;
 return (
 <button key={t.from.key} className={`sd-trans${isWorst ? " sd-trans--worst" : ""}`}
 onClick={() => { setStage(t.from.key); open("stage", { index: t.index }); }}>
 <div className="sd-trans__head">
 <span className="sd-trans__label">{t.from.label} → {t.to.label}</span>
 {isWorst ? <Chip status="amber">Largest gap</Chip> : <span className="ci-faint" style={{ fontSize: 11 }}>{t.avgDays}d avg</span>}
 </div>
 <div className="sd-trans__row">
 <span><b style={{ color: "var(--ci-text)" }}>{fmt(t.population)}</b> <span className="ci-faint">start</span></span>
 <span><b style={{ color: "var(--ci-green)" }}>{fmt(t.progressed)}</b> <span className="ci-faint">progressed</span></span>
 <span><b style={{ color: t.rate >= 60 ? "var(--ci-green)" : t.rate >= 40 ? "var(--ci-cyan)" : "var(--ci-amber)" }}>{t.rate}%</b></span>
 <span><b style={{ color: "var(--ci-amber)" }}>{fmt(t.notProgressed)}</b> <span className="ci-faint">in-stage</span></span>
 </div>
 <div className="sd-split__track">
 <div className="sd-split__fill" style={{ width: "100%" }} />
 <div className="sd-split__conv" style={{ width: `${t.rate}%` }} />
 </div>
 </button>
 );
 })}
 </div>
 </Drawer>
 );
 }

 // ---------- SINGLE STAGE ----------
 const a = stageAnalysis(idx);
 const barrierRows = STAGE_BARRIERS.map(b => ({ ...b, count: Math.round(b.pct / 100 * a.notProgressed) }));
 const topBarrier = barrierRows[0];

 const regionBacklog = STAGE_REGION_SPLIT.map(r => {
 const pop = Math.round(a.population * r.share);
 return { name: r.name, backlog: pop - Math.round(pop * r.conv / 100) };
 }).sort((x, y) => y.backlog - x.backlog);
 const totalBacklog = regionBacklog.reduce((s, r) => s + r.backlog, 0);
 const top2Pct = Math.round(((regionBacklog[0].backlog + regionBacklog[1].backlog) / totalBacklog) * 100);

 const regionComputed = STAGE_REGION_SPLIT.map(r => {
 const pop = Math.round(a.population * r.share);
 return { name: r.name, conv: r.conv, backlog: pop - Math.round(pop * r.conv / 100) };
 });
 const hiConv = Math.max(...regionComputed.map(r => r.conv));
 const loConv = Math.min(...regionComputed.map(r => r.conv));
 const maxBacklog = Math.max(...regionComputed.map(r => r.backlog));

 const attention = STAGE_ATTENTION.filter(x =>
 (!barrier || x.blocker === barrier) &&
 (!regionF || x.region === regionF) &&
 (!sportF || x.sport === sportF));

 const prevDisabled = a.index <= 0;
 const nextDisabled = a.index >= PIPELINE.length - 2;
 const goto = (i: number) => { setStage(PIPELINE[i].key); open("stage", { index: i }); };

 const tabs: { id: Tab; label: string }[] = [
 { id: "overview", label: "Overview" }, { id: "region", label: "Region" },
 { id: "sport", label: "Sport" }, { id: "source", label: "Source" }, { id: "athletes", label: "Athletes" },
 ];

 const head = (
 <>
 <div className="sd-eyebrow">Pipeline Stage Analysis</div>
 <div className="sd-nav">
 <button className="sd-nav__btn" disabled={prevDisabled} onClick={() => !prevDisabled && goto(a.index - 1)}
 title={prevDisabled ? "" : `${PIPELINE[a.index - 1].label}`}>← Prev</button>
 <button className="sd-nav__btn" disabled={nextDisabled} onClick={() => !nextDisabled && goto(a.index + 1)}
 title={nextDisabled ? "" : `${PIPELINE[a.index + 1].label} →`}>Next →</button>
 </div>
 </>
 );

 const activeFilterLabel = barrier || regionF || sportF;

 return (
 <Drawer open wide onClose={onClose} title={`${a.from.label} → ${a.to.label}`} headExtra={head}
 sub={`${fmt(a.population)} in stage · ${a.rate}% progression · target ${a.target}%`}>

 <div className="sd-kpis">
 <Kpi v={fmt(a.population)} l="Current stage population" />
 <Kpi v={fmt(a.progressed)} l="Progressed" tone="var(--ci-green)" />
 <Kpi v={`${a.rate}%`} l="Progression rate" tone="var(--ci-cyan)" />
 <Kpi v={fmt(a.notProgressed)} l="Not yet progressed" tone="var(--ci-amber)" />
 <Kpi v={`${a.avgDays} days`} l="Avg time in stage" />
 <Kpi v={`${a.target}%`} l="National target" />
 <Kpi v={`${a.gap >= 0 ? "+" : ""}${a.gap} pts`} l="Gap to target" tone={a.gap >= 0 ? "var(--ci-green)" : "var(--ci-red)"} />
 </div>

 <div className="ci-insight" style={{ marginTop: 14, borderColor: "rgba(217,130,10,0.28)", background: "var(--ci-amber-soft)" }}>
 <span className="ci-insight__icon" style={{ color: "var(--ci-amber)" }}><Icon.alert style={{ width: 15, height: 15 }} /></span>
 <div className="ci-insight__txt" style={{ fontSize: 12 }}>{pathwayGapText(a.index)}</div>
 </div>

 <div className="sd-tabs">
 {tabs.map(t => (
 <button key={t.id} className={`sd-tab${tab === t.id ? " sd-tab--active" : ""}`} onClick={() => setTab(t.id)}>{t.label}</button>
 ))}
 </div>

 {tab === "overview" && (
 <>
 <div className="sd-section">Progression Barriers</div>
 <div className="sd-barriers">
 {barrierRows.map(b => {
 const sel = barrier === b.label;
 return (
 <div key={b.label} className={`sd-barrier${sel ? " sd-barrier--sel" : ""}`}
 onClick={() => { setBarrier(sel ? null : b.label); setTab("athletes"); }}>
 <span className="sd-barrier__label">{b.label}</span>
 <span className="sd-barrier__count ci-num">{fmt(b.count)}</span>
 <span className="sd-barrier__pct ci-faint">{b.pct}%</span>
 <span className="sd-barrier__trend" style={{ color: b.trend > 0 ? "var(--ci-amber)" : b.trend < 0 ? "var(--ci-green)" : "var(--ci-text-faint)" }}>
 {b.trend > 0 ? `↑ ${b.trend}%` : b.trend < 0 ? `↓ ${Math.abs(b.trend)}%` : "—"}
 </span>
 </div>
 );
 })}
 </div>

 <div className="sd-intervention">
 <div className="sd-intervention__k"><Icon.brain style={{ width: 14, height: 14 }} /> Recommended Intervention</div>
 <p className="sd-intervention__txt">
 <b>{fmt(topBarrier.count)}</b> {a.from.label.toLowerCase()} athletes are currently waiting for {topBarrier.label.toLowerCase()}. <b>{regionBacklog[0].name}</b> and <b>{regionBacklog[1].name}</b> represent <b>{top2Pct}%</b> of this backlog.
 </p>
 <p className="sd-intervention__sub">Suggested response: create a priority development cohort for athletes scoring 85+ and route the remainder to available regional programs.</p>
 {cohortDone && <div className="sd-cohort-done"><Icon.target style={{ width: 13, height: 13 }} /> Cohort created · routed to Action Center</div>}
 <div className="sd-intervention__actions">
 <Button size="sm" variant="primary" icon="plus" onClick={() => setCohort(true)}>Create Cohort</Button>
 <Button size="sm" icon="users" onClick={() => setTab("athletes")}>View Athletes</Button>
 <Button size="sm" icon="bolt" onClick={() => { toast(`Opening Action Center · ${a.from.label} → ${a.to.label} · ${topBarrier.label}`); navigate("actions"); }}>Open Action Center</Button>
 <Button size="sm" variant="ghost" onClick={onClose}>Dismiss</Button>
 </div>
 </div>
 </>
 )}

 {tab === "region" && (
 <>
 <div className="sd-section">Progression by region <span className="ci-faint" style={{ fontWeight: 400 }}>· click to filter athletes</span></div>
 <SplitBars rows={STAGE_REGION_SPLIT} population={a.population} selected={regionF}
 onPick={n => { setRegionF(regionF === n ? null : n); }}
 badge={r => <>
 {r.conv === hiConv && <Chip status="green">Highest</Chip>}
 {r.conv === loConv && <Chip status="amber">Lowest</Chip>}
 {r.backlog === maxBacklog && <Chip status="ghost">Largest backlog</Chip>}
 </>} />
 {regionF && <div className="sd-filterbar">Filtered: <b>{regionF}</b> <button onClick={() => setTab("athletes")}>View athletes →</button></div>}
 </>
 )}

 {tab === "sport" && (
 <>
 <div className="sd-section">Progression by sport <span className="ci-faint" style={{ fontWeight: 400 }}>· click to filter athletes</span></div>
 <SplitBars rows={STAGE_SPORT_SPLIT} population={a.population} selected={sportF}
 onPick={n => { setSportF(sportF === n ? null : n); }} />
 {sportF && <div className="sd-filterbar">Filtered: <b>{sportF}</b> <button onClick={() => setTab("athletes")}>View athletes →</button></div>}
 </>
 )}

 {tab === "source" && (
 <>
 <div className="sd-section">Discovery source · progression & stage duration</div>
 <div className="sd-src">
 <div className="sd-src__row sd-src__row--head">
 <span>Source</span><span>Athletes</span><span>Progression</span><span>Avg days</span>
 </div>
 {STAGE_SOURCE_SPLIT.map(s => (
 <div key={s.name} className="sd-src__row">
 <span className="sd-src__name">{s.name}</span>
 <span className="ci-num">{fmt(Math.round(a.population * s.share))}</span>
 <span style={{ color: s.conv >= 50 ? "var(--ci-green)" : s.conv >= 38 ? "var(--ci-cyan)" : "var(--ci-amber)", fontWeight: 700 }}>{s.conv}%</span>
 <span className="ci-num">{s.days}d</span>
 </div>
 ))}
 </div>
 </>
 )}

 {tab === "athletes" && (
 <>
 <div className="sd-section">Athletes Requiring Attention
 {activeFilterLabel && <span className="ci-faint" style={{ fontWeight: 400 }}> · {activeFilterLabel}</span>}
 {activeFilterLabel && <button className="sd-clear" onClick={() => { setBarrier(null); setRegionF(null); setSportF(null); }}>clear</button>}
 </div>
 <div className="sd-attn">
 {attention.map(x => (
 <div key={x.id} className="sd-attn__row" onClick={() => setPreview(x)}>
 <div className="sd-attn__main">
 <span className="sd-attn__name">{x.name}</span>
 <span className="ci-faint" style={{ fontSize: 10.5 }}>{x.sport} · {x.region} · {x.days}d in stage · score {x.score}</span>
 </div>
 <span className="sd-attn__blk ci-faint">{x.blocker}</span>
 <Chip status={PRI[x.priority]}>{x.priority}</Chip>
 </div>
 ))}
 {attention.length === 0 && <div className="ci-faint" style={{ fontSize: 12, padding: "8px 0" }}>No athletes match this filter.</div>}
 </div>
 </>
 )}

 {preview && (
 <div className="sd-modal-overlay" onClick={() => setPreview(null)}>
 <div className="sd-preview" onClick={e => e.stopPropagation()}>
 <div className="sd-preview__head">
 <div className="ci-ident__av" style={{ width: 44, height: 44, borderRadius: 12, fontSize: 15, background: "var(--ci-grad-cyan)" }}>
 {preview.name.split(" ").map(w => w[0]).slice(0, 2).join("")}
 </div>
 <div>
 <div style={{ fontWeight: 800, fontSize: 15 }}>{preview.name}</div>
 <div className="ci-faint" style={{ fontSize: 11.5 }}>{preview.sport} · age {preview.age} · {preview.region}</div>
 </div>
 <button className="ci-drawer__close" style={{ marginLeft: "auto" }} onClick={() => setPreview(null)}><Icon.x style={{ width: 14, height: 14 }} /></button>
 </div>
 <div className="sd-preview__grid">
 <Kpi v={a.from.label} l="Current stage" />
 <Kpi v={preview.score} l="Potential score" tone="var(--ci-cyan)" />
 <Kpi v={`${preview.days}d`} l="Days in stage" tone="var(--ci-amber)" />
 </div>
 <div className="ci-insight" style={{ margin: "4px 0 12px" }}>
 <span className="ci-insight__icon"><Icon.alert style={{ width: 14, height: 14 }} /></span>
 <div className="ci-insight__txt" style={{ fontSize: 11.5 }}><b>Blocker:</b> {preview.blocker}</div>
 </div>
 <div style={{ display: "flex", gap: 8 }}>
 <Button size="sm" variant="primary" icon="user" onClick={() => { navigate("athlete360", { id: preview.id }); }}>Open Athlete 360</Button>
 <Button size="sm" icon="plus" onClick={() => { toast(`Action created · ${preview.action} · ${preview.name}`); setPreview(null); }}>Create Action</Button>
 </div>
 </div>
 </div>
 )}

 {cohort && (
 <CohortModal stageLabel={a.from.label} region={regionBacklog[0].name} barrier={topBarrier.label}
 onClose={() => setCohort(false)}
 onCreate={name => { setCohort(false); setCohortDone(true); setTab("overview"); toast(`Cohort created · ${name}`); }} />
 )}
 </Drawer>
 );
}

function CohortModal({ stageLabel, region, barrier, onClose, onCreate }:
 { stageLabel: string; region: string; barrier: string; onClose: () => void; onCreate: (name: string) => void }) {
 const [name, setName] = React.useState(`${stageLabel} Athletes Awaiting Development – ${region}`);
 const [score, setScore] = React.useState("85");
 const [priority, setPriority] = React.useState("High");
 React.useEffect(() => {
 const h = (e: KeyboardEvent) => e.key === "Escape" && onClose();
 window.addEventListener("keydown", h);
 return () => window.removeEventListener("keydown", h);
 }, [onClose]);
 return (
 <div className="sd-modal-overlay" onClick={onClose}>
 <div className="sd-cohort" onClick={e => e.stopPropagation()}>
 <div className="sd-cohort__head">
 <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800 }}>Create Intervention Cohort</h3>
 <button className="ci-drawer__close" onClick={onClose}><Icon.x style={{ width: 14, height: 14 }} /></button>
 </div>
 <label className="sd-field"><span>Cohort Name</span><input value={name} onChange={e => setName(e.target.value)} /></label>
 <div className="sd-field-row">
 <label className="sd-field"><span>Stage</span><input value={`${stageLabel} → Development`} readOnly /></label>
 <label className="sd-field"><span>Region</span><input defaultValue={region} /></label>
 </div>
 <div className="sd-field-row">
 <label className="sd-field"><span>Barrier</span><input defaultValue={barrier} readOnly /></label>
 <label className="sd-field"><span>Min Potential Score</span><input value={score} onChange={e => setScore(e.target.value)} /></label>
 </div>
 <div className="sd-field-row">
 <label className="sd-field"><span>Priority</span>
 <select value={priority} onChange={e => setPriority(e.target.value)}>
 <option>High</option><option>Medium</option><option>Low</option>
 </select>
 </label>
 <label className="sd-field"><span>Owner</span><input defaultValue="Pathway Operations" /></label>
 </div>
 <div className="sd-cohort__foot">
 <Button size="sm" variant="ghost" onClick={onClose}>Cancel</Button>
 <Button size="sm" variant="primary" icon="plus" onClick={() => onCreate(name)}>Create Cohort</Button>
 </div>
 </div>
 </div>
 );
}
","import React from "react";
import "../../command.css";
import { useApp } from "../../context/AppContext";
import { CommandContext, CmdDrawerState, DrawerKind } from "./command/ctx";
import { CmdHeader } from "./command/CmdHeader";
import { KpiStrip } from "./command/KpiStrip";
import { PipelineRow } from "./command/PipelineRow";
import { MapRow, VelocityRow } from "./command/MapVelocityRow";
import { MatrixRow, OpportunitiesRow } from "./command/MatrixOppRow";
import { RisksRow, ActionCenterRow } from "./command/RiskActionRow";
import { AiInsightRow, ActivityRow } from "./command/AiActivityRow";
import { CmdDrawer } from "./command/CmdDrawer";
import { StageDrawer } from "./command/StageDrawer";
import { StatusLegend } from "../common";

export function CommandCenter() {
 const { toast } = useApp();
 const [stage, setStage] = React.useState<string | null>(null);
 const [region, setRegion] = React.useState<string | null>(null);
 const [sport, setSport] = React.useState<string | null>(null);
 const [linkedAction, setLinkedAction] = React.useState<string | null>(null);
 const [drawer, setDrawer] = React.useState<CmdDrawerState | null>(null);

 const open = React.useCallback((kind: DrawerKind, data: any = null) => setDrawer({ kind, data }), []);
 const ctx = { stage, setStage, region, setRegion, sport, setSport, linkedAction, setLinkedAction, open, toast };

 // Closing the pipeline/stage drawer must also clear the stage highlight so the
 // dashboard returns to its original state (no lingering cross-filter).
 const closeDrawer = React.useCallback(() => {
 setDrawer(d => {
 if (d && (d.kind === "stage" || d.kind === "pipeline")) setStage(null);
 return null;
 });
 }, []);

 const isStage = drawer && (drawer.kind === "stage" || drawer.kind === "pipeline");

 return (
 <CommandContext.Provider value={ctx}>
 <div className="ci-fade">
 <CmdHeader />
 <div style={{ display: "flex", justifyContent: "flex-end", padding: "0 2px 8px" }}><StatusLegend /></div>
 <div className="ci-grid">
 <KpiStrip />
 <PipelineRow />
 <MapRow />
 <VelocityRow />
 <MatrixRow />
 <OpportunitiesRow />
 <RisksRow />
 <ActionCenterRow />
 <AiInsightRow />
 <ActivityRow />
 </div>
 </div>
 {isStage
 ? <StageDrawer state={drawer} onClose={closeDrawer} />
 : <CmdDrawer state={drawer} onClose={() => setDrawer(null)}
 onAction={a => { toast(a + " — action started"); setDrawer(null); }} />}
 </CommandContext.Provider>
 );
}
","/* ============================================================
 National Talent Radar — component styles (PREMIUM LIGHT)
 ============================================================ */

/* cohort builder filter chips */
.tr-builder { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px; }
.tr-chip {
 display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px; border-radius: 999px;
 border: 1px dashed var(--ci-border-strong); background: #fff; color: var(--ci-text-dim);
 font-size: 11px; font-weight: 600; cursor: pointer; transition: all .14s ease; user-select: none;
}
.tr-chip:hover { border-color: var(--ci-cyan); color: var(--ci-cyan); }
.tr-chip--on { border-style: solid; border-color: var(--ci-cyan); background: var(--ci-cyan-soft); color: var(--ci-cyan); }

/* benchmark athlete rows */
.tr-bench { display: flex; flex-direction: column; gap: 8px; }
.tr-benchrow {
 border: 1px solid var(--ci-border); border-radius: var(--ci-radius-sm); padding: 9px 11px;
 background: var(--ci-bg-0); cursor: pointer; transition: all .15s ease;
}
.tr-benchrow:hover { border-color: var(--ci-border-strong); background: var(--ci-bg-3); }
.tr-benchrow--sel { border-color: var(--ci-cyan); background: var(--ci-cyan-soft); }
.tr-benchrow__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.tr-benchrow__name { font-size: 12.5px; font-weight: 700; color: var(--ci-text); }
.tr-benchrow__meta { font-size: 10.5px; color: var(--ci-text-faint); margin-top: 1px; }
.tr-gap { font-size: 12px; font-weight: 800; }

/* opportunity score gauge chip */
.tr-oppscore { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-radius: var(--ci-radius-sm);
 background: var(--ci-amber-soft); border: 1px solid rgba(217,130,10,0.22); margin-bottom: 10px; }
.tr-oppscore__num { font-size: 22px; font-weight: 800; color: var(--ci-amber); line-height: 1; }
.tr-oppscore__lab { font-size: 10px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--ci-text-faint); font-weight: 700; }

/* cohort table tuning (reuses ci-table) */
.tr-table td, .tr-table th { padding: 7px 8px; }
.tr-pct { font-weight: 700; }
