export const COHORT: CohortAthlete[] = CN.map((c, i) => ({
 id: 'C' + i,
 name: c[0] as string,
 sport: c[1] as string,
 region: c[2] as string,
 age: c[3] as number,
 localPct: c[4] as number,
 nationalPct: c[5] as number,
 globalGap: c[6] as number,
 velocity: c[7] as number,
 stage: c[8] as string,
 source: c[9] as string,
}))

// ---- Talent action queue ----
export interface TalentAction {
 id: string
 title: string
 pri: Status
 cohort: string
 owner: string
 state: string
 region?: string
}
export const TALENT_ACTIONS: TalentAction[] = [
 {
