 if (f.age && !(a.age >= 16 && a.age <= 21)) return false;
 if (f.top && a.nationalPct < 90) return false;
 if (f.fast && a.velocity < 80) return false;
 if (f.notElite && a.stage === "Elite") return false;
 return true;
 });
