const MOMENTUM_TITLE = "6-Week Performance Momentum Index";

export function AthleteTable({ rows, onSelect, columns = ["cpi", "percentile", "readiness", "risk", "momentum"] }:
 { rows: Athlete[]; onSelect: (a: Athlete) => void; columns?: string[] }) {
 const head: Record<string, string> = { sport: "Sport", region: "Region", cpi: "CPI", percentile: "National Percentile", readiness: "Readiness", risk: "Risk", momentum: "Momentum" };
 const headTitle: Record<string, string | undefined> = { cpi: CPI_TITLE, momentum: MOMENTUM_TITLE };
 return (
 <table className="ci-table">
 <thead>
