 </div>
 </div>
 </td>
 <td><Chip status="ghost">{a.stage}</Chip></td>
 {columns.map(c => {
 if (c === "sport") return <td key={c}>{a.sport}</td>;
 if (c === "region") return <td key={c}>{a.region}</td>;
 if (c === "cpi") return <td key={c} title={CPI_TITLE}><Meter v={a.potential} color={SC[a.status]} /></td>;
 if (c === "percentile") return <td key={c} className="ci-num">P{a.benchmark}</td>;
 if (c === "readiness") return <td key={c} title={`Readiness Index: ${a.readiness} / 100`}><Meter v={a.readiness} color="var(--ci-cyan)" /></td>;
 if (c === "risk") return <td key={c} className="ci-num" style={{ color: a.injuryRisk > 62 ? "var(--ci-red)" : a.injuryRisk > 42 ? "var(--ci-amber)" : "var(--ci-text-dim)" }}>{a.injuryRisk}%</td>;
 if (c === "momentum") return <td key={c} className="ci-num" title={MOMENTUM_TITLE} style={{ color: a.momentum >= 0 ? "var(--ci-green)" : "var(--ci-red)" }}>{a.momentum >= 0 ? "+" : ""}{a.momentum}</td>;
 return <td key={c}></td>;
 })}
 <td><span className={`ci-dot ci-dot--${a.status}`} /></td>
 </tr>
 ))}
 </tbody>
 </table>
 );
}

function Meter({ v, color }: { v: number; color: string }) {
