import { AthleteTable } from "../AthleteTable";
import { useApp } from "../../context/AppContext";
import { ATHLETES, Athlete } from "../../data/demo";

const SEGMENTS = ["All", "High Potential", "At Risk", "Elite Pathway", "Para Athlete"];

export function Athletes({ onAthlete }: { onAthlete: (a: Athlete) => void }) {
 const { navigate } = useApp();
 const [seg, setSeg] = React.useState("All");
 const [q, setQ] = React.useState("");

 const rows = ATHLETES.filter(a => {
 if (q && !a.name.toLowerCase().includes(q.toLowerCase())) return false;
 if (seg === "High Potential") return a.potential > 84;
 if (seg === "At Risk") return a.injuryRisk > 55;
 if (seg === "Elite Pathway") return a.stage === "Elite Pathway" || a.stage === "International Competition" || a.stage === "International Medal";
 if (seg === "Para Athlete") return a.sport === "Para Athletics";
 return true;
 });

 return (
 <div className="ci-fade">
 <PageHead title="Athletes" desc="The full tracked population across every stage and pathway. Search, segment and drill into any athlete's 360° profile."
 actions={<Button icon="user" variant="primary" onClick={() => navigate("athlete360")}>Open Athlete 360</Button>} />

 <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 10 }}><StatusLegend /></div>

 <Panel hover title={`${rows.length} athletes`} sub="Click a row to open the profile drawer"
 right={
 <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
 <div className="ci-search" style={{ minWidth: 200, padding: "6px 12px" }}>
 <input placeholder="Search name…" value={q} onChange={e => setQ(e.target.value)} aria-label="Search athletes" />
 </div>
 <div className="ci-seg">
 {SEGMENTS.map(s => (
 <button key={s} className={`ci-seg__btn ${seg === s ? "ci-seg__btn--active" : ""}`} onClick={() => setSeg(s)}>{s}</button>
 ))}
 </div>
 </div>
 }>
 <AthleteTable rows={rows} onSelect={onAthlete} columns={["sport", "region", "cpi", "percentile", "readiness", "risk", "momentum"]} />
 </Panel>
 </div>
 );
}
