","import React from "react";
import { Panel, Counter, Sparkline } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { Drawer } from "../Drawer";
import { Icon } from "../Icons";
import { useApp } from "../../context/AppContext";
import { ACTION_QUEUE, ActionItem, INTERVENTION_OUTCOMES, OUTCOME_TREND, CONTEXTUAL_ACTIONS } from "../../data/demo";

const PRI: Record<string, string> = { green: "var(--ci-green)", amber: "var(--ci-amber)", red: "var(--ci-red)", cyan: "var(--ci-cyan)" };
const PRIORITY_TONE: Record<string, any> = { High: "red", Medium: "amber", Low: "green" };
const LANES = [
 { key: "red", label: "Critical", icon: "alert" as const },
 { key: "amber", label: "Attention", icon: "flag" as const },
 { key: "cyan", label: "Opportunity", icon: "star" as const },
 { key: "green", label: "On Track", icon: "activity" as const },
];
// Enriched extra board items (req 18) using contextual action vocabulary (req 19).
const EXTRA: ActionItem[] = [
 { id: "a6", title: "Jazan swimming surge — allocate scouting capacity", meta: "+34% identification · resourcing", pri: "cyan", type: "Create Cohort",
 subject: "Jazan Swimming Cohort", priority: "Medium", owner: "Jazan Regional Academy Team", due: "Due 4 days", sla: "green", slaLabel: "On track", source: "AI Intelligence" },
 { id: "a7", title: "Nawaf Al-Shammari — recovery trending down 3 weeks", meta: "Recovery 58% · Cycling · Northern Borders", pri: "amber", type: "Assign Coach",
 subject: "Nawaf Al-Shammari", priority: "High", owner: "Northern Borders Medical Team", due: "Due 2 days", sla: "amber", slaLabel: "At risk", source: "Wearables" },
 { id: "a8", title: "Layan Al-Otaibi — confirm podium pathway placement", meta: "Percentile 96 · Para Athletics", pri: "green", type: "Nominate for Elite",
 subject: "Layan Al-Otaibi", priority: "Low", owner: "National Para Pathway Team", due: "Due 6 days", sla: "green", slaLabel: "On track", source: "Development Journey" },
];

const DetailRow = ({ icon, label, value }: { icon: any; label: string; value?: React.ReactNode }) =>
 value ? (
 <div className="ci-act-detail">
 {React.createElement(icon, { style: { width: 12, height: 12 } })}
 <span className="ci-faint">{label}</span><span className="ci-act-detail__v">{value}</span>
 </div>
 ) : null;

// Contextual action drawer — opened from a card's "Open" (replaces generic "Act", req 19).
function ActionDrawer({ action, onClose }: { action: ActionItem | null; onClose: () => void }) {
 const { toast } = useApp();
 if (!action) return null;
 const fire = (a: string) => { toast(`${a} — ${action.subject || action.title}`); onClose(); };
 return (
 <Drawer open onClose={onClose} title={action.subject || action.title}
 sub={action.subject ? action.title : undefined}
 headExtra={<div className="ci-eyebrow" style={{ marginBottom: 6 }}>Action detail</div>}
 footer={<><Button variant="primary" icon="bolt" onClick={() => fire(action.type)}>{action.type}</Button>
 <Button icon="user" onClick={() => fire("Assign")}>Assign</Button>
 <Button variant="ghost" onClick={() => fire("Complete")}>Complete</Button></>}>
 <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap", marginBottom: 14 }}>
 {action.priority && <Chip status={PRIORITY_TONE[action.priority]}>Priority {action.priority}</Chip>}
 {action.sla && <Chip status={action.sla}>{action.slaLabel}</Chip>}
 <Chip status="ghost">{action.type}</Chip>
 </div>
 <div className="ci-dim" style={{ fontSize: 12.5, lineHeight: 1.5, marginBottom: 14 }}>{action.meta}</div>
 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 10, marginBottom: 16 }}>
 <DetailRow icon={Icon.users} label="Owner" value={action.owner} />
 <DetailRow icon={Icon.watch} label="Due" value={action.due} />
 <DetailRow icon={Icon.brain} label="Source" value={action.source} />
 <DetailRow icon={Icon.user} label="Athlete / cohort" value={action.subject} />
 </div>
 <div className="ci-divider" />
 <div className="ci-eyebrow" style={{ marginBottom: 8 }}>Contextual actions</div>
 <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
 {CONTEXTUAL_ACTIONS.map(a => (
 <Button key={a} size="sm" onClick={() => fire(a)}>{a}</Button>
 ))}
 </div>
 </Drawer>
 );
}

export function Actions() {
 const { toast } = useApp();
 const [open, setOpen] = React.useState<ActionItem | null>(null);
 const all = [...ACTION_QUEUE, ...EXTRA];
 return (
 <div className="ci-fade">
 <PageHead title="Actions" desc="Every insight connects to a next best action. Prioritized, assignable and tracked to outcome — no passive dashboards."
 actions={<Button icon="plus" variant="primary" onClick={() => toast("New intervention created")}>Create Intervention</Button>} />

 <div className="ci-grid">
 {LANES.map(lane => {
 const items = all.filter(a => a.pri === lane.key);
 const I = Icon[lane.icon];
 return (
 <Panel key={lane.key} span={3} hover title={lane.label}
 right={<span className="ci-chip ci-chip--ghost">{items.length}</span>}>
 <div className="ci-actions-list">
 {items.length === 0 && <div className="ci-faint" style={{ fontSize: 12, padding: "10px 2px" }}>Nothing here — all clear.</div>}
 {items.map(a => (
 <div className="ci-action" key={a.id} style={{ flexDirection: "column", alignItems: "stretch", gap: 8 }}>
 <div style={{ display: "flex", gap: 10 }}>
 <span style={{ color: PRI[lane.key], flex: "none" }}><I style={{ width: 15, height: 15 }} /></span>
 <div className="ci-action__body">
 <div className="ci-action__title" style={{ fontSize: 12 }}>{a.title}</div>
 <div className="ci-action__meta">{a.meta}</div>
 </div>
 </div>
 <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
 {a.priority && <Chip status={PRIORITY_TONE[a.priority]}>Priority {a.priority}</Chip>}
 {a.sla && <Chip status={a.sla}>{a.slaLabel}</Chip>}
 <Chip status={a.pri as any}>{a.type}</Chip>
 </div>
 <div className="ci-act-details">
 <DetailRow icon={Icon.users} label="Owner" value={a.owner} />
 <DetailRow icon={Icon.watch} label="Due" value={a.due} />
 <DetailRow icon={Icon.user} label="Subject" value={a.subject} />
 <DetailRow icon={Icon.brain} label="Source" value={a.source} />
 </div>
 <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
 <Button size="sm" variant="ghost" onClick={() => setOpen(a)}>Open</Button>
 <Button size="sm" variant="ghost" onClick={() => toast(`Assigned · ${a.owner || a.title}`)}>Assign</Button>
 <Button size="sm" variant="ghost" onClick={() => toast(`Completed · ${a.subject || a.title}`)}>Complete</Button>
 </div>
 </div>
 ))}
 </div>
 </Panel>
 );
 })}

 {/* Priority 2 — Intervention Outcomes (req 20) */}
 <Panel span={12} hover title="Intervention Outcomes" sub="Operational health of the action pipeline"
 right={<Chip status="green">82% success rate</Chip>}>
 <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "stretch" }}>
 {INTERVENTION_OUTCOMES.map(k => (
 <div key={k.label} className="ci-oc">
 <span className="ci-oc__label">{k.label}</span>
 <span className="ci-oc__value" style={{ color: PRI[k.status] }}>
 <Counter value={k.value} decimals={k.decimals || 0} />{k.unit && <span className="ci-oc__unit">{k.unit}</span>}
 </span>
 </div>
 ))}
 <div className="ci-oc ci-oc--trend">
 <span className="ci-oc__label">Completed · 12 mo trend</span>
 <Sparkline data={OUTCOME_TREND} color="var(--ci-green)" h={34} />
 </div>
 </div>
 </Panel>
 </div>

 <ActionDrawer action={open} onClose={() => setOpen(null)} />
 </div>
 );
}
","import React from "react";
import { Panel } from "../primitives";
import { Chip } from "../KpiCard";
import { PageHead } from "../common";
import { Button } from "../Button";
import { Drawer } from "../Drawer";
import { Icon } from "../Icons";
import { useApp } from "../../context/AppContext";
import { AI_INSIGHTS, PREDICTION_QUEUE, PredictionInsight } from "../../data/demo";

const TAG_STATUS: Record<string, any> = { Opportunity: "cyan", "Talent Transfer": "green", Risk: "amber", Performance: "green" };

// Right-side explainability drawer for a prediction insight (req 17).
function WhyDrawer({ insight, onClose }: { insight: PredictionInsight | null; onClose: () => void }) {
 const { toast } = useApp();
 if (!insight) return null;
 const maxFactor = insight.why.length;
 return (
 <Drawer open onClose={onClose} title="Why this insight was generated"
 sub={`${insight.signal} · ${insight.subject}`}
 headExtra={<div className="ci-eyebrow" style={{ marginBottom: 6 }}>Explainability</div>}
 footer={<Button variant="primary" icon="bolt" onClick={() => { toast(`${insight.action} — ${insight.subject}`); onClose(); }}>{insight.action}</Button>}>
 <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 14 }}>
 <Chip status={insight.urgency}>{insight.urgencyLabel}</Chip>
 <Chip status="ghost">{insight.kind}</Chip>
 <span className="ci-faint" style={{ fontSize: 11, marginLeft: "auto" }}>{insight.freshness}</span>
 </div>

 <div className="ci-eyebrow" style={{ marginBottom: 8 }}>Ranked top factors</div>
 <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 16 }}>
 {insight.why.map((f, i) => (
 <div key={f.label} className="ci-action" style={{ padding: "9px 11px" }}>
 <span className="ci-why__rank">{i + 1}</span>
 <div className="ci-action__body">
 <div className="ci-action__title" style={{ fontSize: 12 }}>{f.label}</div>
 <div className="ci-action__meta">Contribution weight {Math.round(100 - (i / maxFactor) * 45)}%</div>
 </div>
 <span className="ci-num" style={{ fontSize: 12.5, fontWeight: 700, color: "var(--ci-text)" }}>{f.value}</span>
 </div>
 ))}
 </div>

 <div style={{ display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 12, marginBottom: 16 }}>
 <div className="ci-stat"><span className="ci-stat__v">{insight.confidence}%</span><span className="ci-stat__l">Confidence</span></div>
 <div className="ci-stat"><span className="ci-stat__v" style={{ fontSize: 13, fontWeight: 700 }}>{insight.freshness}</span><span className="ci-stat__l">Data freshness</span></div>
 </div>

 <div className="ci-divider" />
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Affected athlete / cohort</div>
 <div className="ci-dim" style={{ fontSize: 12.5, marginBottom: 12 }}>{insight.affected}</div>
 <div className="ci-eyebrow" style={{ marginBottom: 6 }}>Last model evaluation</div>
 <div className="ci-faint" style={{ fontSize: 11.5 }}>{insight.lastEval}</div>
 </Drawer>
 );
}

export function AIIntelligence() {
 const { toast, navigate } = useApp();
 const [why, setWhy] = React.useState<PredictionInsight | null>(null);
 return (
 <div className="ci-fade">
 <PageHead title="AI Intelligence" desc="Continuous machine analysis across the population — surfacing what changed, why it matters, and what to do next."
 actions={<Button icon="brain" variant="primary" onClick={() => toast("Generating fresh intelligence briefing…")}>Generate Briefing</Button>} />

 <div className="ci-grid">
 <Panel span={8} hover title="Intelligence Feed" sub="Ranked by impact and confidence">
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {AI_INSIGHTS.map((it, i) => (
 <div key={i} className="ci-action" style={{ alignItems: "flex-start" }}>
 <span style={{ color: "var(--ci-cyan)", flex: "none", marginTop: 2 }}><Icon.spark style={{ width: 16, height: 16 }} /></span>
 <div className="ci-action__body">
 <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 4 }}>
 <Chip status={TAG_STATUS[it.tag]}>{it.tag}</Chip>
 <span className="ci-faint" style={{ fontSize: 10.5 }}>confidence {88 - i * 6}%</span>
 </div>
 <div style={{ fontSize: 12.5, color: "var(--ci-text)", lineHeight: 1.5 }}>{it.t}</div>
 </div>
 <Button size="sm" variant="ghost" onClick={() => navigate("actions")}>Act</Button>
 </div>
 ))}
 </div>
 </Panel>

 <div className="ci-span-4" style={{ display: "flex", flexDirection: "column", gap: 14 }}>
 <Panel hover title="Model Confidence" sub="Prediction reliability by domain">
 {[["Talent identification", 91, "green"], ["Injury forecasting", 84, "green"], ["Transfer matching", 77, "amber"], ["Podium projection", 69, "amber"]].map(([l, v, c]: any) => (
 <div key={l} style={{ marginBottom: 10 }}>
 <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, marginBottom: 3 }}>
 <span className="ci-dim">{l}</span><span className="ci-num">{v}%</span>
 </div>
 <div className="ci-meter"><div className="ci-meter__fill" style={{ width: `${v}%`, background: `var(--ci-${c})` }} /></div>
 </div>
 ))}
 </Panel>
 <Panel hover title="Ask Champion IQ" sub="Natural-language intelligence">
 <div className="ci-search" style={{ minWidth: 0, marginBottom: 10 }}>
 <Icon.brain style={{ width: 15, height: 15 }} />
 <input placeholder="e.g. Who should we assess next?" aria-label="Ask AI" />
 </div>
 {["Which regions are under-scouted?", "Who is at risk of dropout?", "Best transfer candidates?"].map(q => (
 <div key={q} className="ci-filter__opt" style={{ borderRadius: 8, marginBottom: 2 }} onClick={() => toast("Analyzing: " + q)}>
 <Icon.search style={{ width: 12, height: 12 }} /> {q}
 </div>
 ))}
 </Panel>
 </div>

 {/* Priority 1 — Prediction & Intervention Queue (reqs 16 & 17) */}
 <Panel span={12} hover title="Prediction & Intervention Queue"
 sub="AI predictions with ranked explanation and a recommended next action"
 right={<Chip status="cyan">{PREDICTION_QUEUE.length} active</Chip>}>
 <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
 {PREDICTION_QUEUE.map(p => (
 <div key={p.id} className="ci-piq">
 <div className="ci-piq__main">
 <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 4 }}>
 <span className="ci-piq__subject">{p.subject}</span>
 <Chip status="ghost">{p.kind}</Chip>
 <Chip status={p.urgency}>{p.urgencyLabel}</Chip>
 </div>
 <div className="ci-piq__signal">
 <span style={{ color: "var(--ci-cyan)" }}><Icon.spark style={{ width: 14, height: 14 }} /></span>
 {p.signal}
 <span className="ci-faint" style={{ fontSize: 11 }}>· confidence {p.confidence}%</span>
 </div>
 <ul className="ci-piq__why">
 {p.why.map(f => (
 <li key={f.label}><span className="ci-dim">{f.label}</span> <b>{f.value}</b></li>
 ))}
 </ul>
 </div>
 <div className="ci-piq__side">
 <Button size="sm" variant="primary" icon="bolt" onClick={() => toast(`${p.action} — ${p.subject}`)}>{p.action}</Button>
 <Button size="sm" variant="ghost" icon="brain" onClick={() => setWhy(p)}>Why?</Button>
 </div>
 </div>
 ))}
 </div>
 </Panel>
 </div>

 <WhyDrawer insight={why} onClose={() => setWhy(null)} />
 </div>
 );
}
","import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props { children?: ReactNode }
interface State { error: Error | null }

// App-wide safety net. A single throwing component must never blank the whole
// platform. Also surfaces the error message into document.title so it can be
// read from runtime diagnostics even when the DOM snapshot is truncated.
//
// NOTE: the inherited React.Component members are declared explicitly because
// this project's @types/react resolution does not surface them on subclasses.
// They are provided by React at runtime.
export class ErrorBoundary extends Component<Props, State> {
 declare props: Props;
 declare state: State;
 declare setState: (s: Partial<State>) => void;

 constructor(props: Props) {
 super(props);
 this.state = { error: null };
 }

 static getDerivedStateFromError(error: Error): State {
 try { document.title = "APPERR " + error.message; } catch { /* noop */ }
 return { error };
 }

 componentDidCatch(error: Error, info: ErrorInfo) {
 const frames = (info.componentStack || "")
 .split("\n").map(s => s.trim()).filter(Boolean).slice(0, 3).join(" <- ");
 try { document.title = "APPERR " + error.message + " :: " + frames; } catch { /* noop */ }
 console.error("[ErrorBoundary]", error, info.componentStack);
 }

 render() {
 const { error } = this.state;
 if (error) {
 return (
 <div style={{ padding: 24, fontFamily: "system-ui, sans-serif", color: "#0b2b3f" }}>
 <h2 style={{ margin: "0 0 8px" }}>Something went wrong rendering this view</h2>
 <pre style={{ whiteSpace: "pre-wrap", background: "#fff3f3", border: "1px solid #f0c0c0",
 borderRadius: 8, padding: 12, fontSize: 12.5, color: "#9b1c1c" }}>
 {error.message}
 {"\n\n"}
 {error.stack}
 </pre>
 </div>
 );
 }
 return <>{this.props.children}</>;
 }
}
","import React from "react";
import "./theme.css";
import "./app.css";
import "./components.css";
import { AppProvider, useApp } from "./context/AppContext";
import { Sidebar } from "./components/shell/Sidebar";
import { TopBar } from "./components/shell/TopBar";
import { FilterBar } from "./components/shell/FilterBar";
import { Toast, AthleteDrawer } from "./components/common";
import { CommandCenter } from "./components/views/CommandCenter";
import { TalentRadar } from "./components/views/TalentRadar";
import { Athletes } from "./components/views/Athletes";
import { Athlete360 } from "./components/views/Athlete360";
import { Performance, Wearables, ComputerVision } from "./components/views/Analytics";
import { GymEquipment, LabAssessments } from "./components/views/PerfExtra";
import { GlobalBenchmark, DevelopmentJourney } from "./components/views/BenchJourney";
import { Actions } from "./components/views/Actions";
import { AIIntelligence } from "./components/views/AIIntelligence";
import { Athlete } from "./data/demo";
import { ErrorBoundary } from "./components/ErrorBoundary";

function Router() {
 const { view } = useApp();
 const [athlete, setAthlete] = React.useState<Athlete | null>(null);
 const pick = (a: Athlete) => setAthlete(a);

 const render = () => {
 switch (view) {
 case "command": return <CommandCenter />;
 case "radar": return <TalentRadar />;
 case "athletes": return <Athletes onAthlete={pick} />;
 case "athlete360": return <Athlete360 />;
 case "performance": return <Performance onAthlete={pick} />;
 case "wearables": return <Wearables onAthlete={pick} />;
 case "vision": return <ComputerVision />;
 case "gym": return <GymEquipment onAthlete={pick} />;
 case "lab": return <LabAssessments onAthlete={pick} />;
 case "benchmark": return <GlobalBenchmark />;
 case "journey": return <DevelopmentJourney />;
 case "actions": return <Actions />;
 case "ai": return <AIIntelligence />;
 default: return <CommandCenter />;
 }
 };

 return (
 <div className="ci-shell">
 <Sidebar />
 <div className="ci-main">
 <TopBar />
 <FilterBar />
 <main className="ci-content">{render()}</main>
 </div>
 <AthleteDrawer athlete={athlete} onClose={() => setAthlete(null)} />
 <Toast />
 </div>
 );
}

export default function App() {
 return (
 <AppProvider>
 <div className="ci-app"><ErrorBoundary><Router /></ErrorBoundary></div>
 </AppProvider>
 );
}
